`timescale 1ns/1ps

// ROM - sine look-up table for the DDS
// DEPTH entries of one full period, unsigned WIDTH-bit values,
// loaded at elaboration from INIT_FILE (generated by scripts/gen_sine.py).
// Synchronous read: data is valid one clock after addr.

module rom #(
    parameter int    DEPTH     = 512,                 // 2**9, matches init_phase[8:0]
    parameter int    WIDTH     = 8,                   // values 0..255
    parameter string INIT_FILE = "sine_lut.mem",
    localparam int   ADDR_W    = $clog2(DEPTH)
)(
    input  logic              clk,
    input  logic [ADDR_W-1:0] addr,                   // phase
    output logic [WIDTH-1:0]  data                    // wave
);

    logic [WIDTH-1:0] mem [DEPTH];

    initial $readmemh(INIT_FILE, mem);

    always_ff @(posedge clk) data <= mem[addr];

endmodule
